// Package engine runs pipelines of steps in parallel and reports what is
// happening as a stream of events.
//
// It knows nothing about builds, archives or SSH. That separation is the whole
// point: the TUI, the plain renderer and the tests all consume the same event
// stream, so none of them is load-bearing.
package engine

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"sync"
)

// Status is where a project or step has got to.
type Status int

const (
	Pending Status = iota
	Running
	Done
	Failed
	Skipped
)

func (s Status) String() string {
	switch s {
	case Running:
		return "running"
	case Done:
		return "done"
	case Failed:
		return "failed"
	case Skipped:
		return "skipped"
	default:
		return "pending"
	}
}

// Kind distinguishes the three things an event can report.
type Kind int

const (
	// KindStep is a step changing status.
	KindStep Kind = iota
	// KindProject is a whole project changing status.
	KindProject
	// KindLog is a line of output from a step.
	KindLog
	// KindProgress is byte-level progress, used for transfers.
