				c.Cleanup()
			}
		}
	}()

	for i, s := range p.Steps {
		if err := ctx.Err(); err != nil {
			r.skipRest(ctx, p, i)
			r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Skipped})
			return nil
		}

		em := &Emitter{ch: r.ch, ctx: ctx, project: p.Project, step: s.Name()}
		r.emit(ctx, Event{Kind: KindStep, Project: p.Project, Step: s.Name(), Status: Running})

		if err := s.Run(ctx, em); err != nil {
			// A cancelled run is not a failure worth reporting as one.
			if ctx.Err() != nil {
				r.skipRest(ctx, p, i)
				r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Skipped})
				return nil
			}
			err = fmt.Errorf("%s: %w", s.Name(), err)
			r.emit(ctx, Event{Kind: KindStep, Project: p.Project, Step: s.Name(), Status: Failed, Err: err})
			r.skipRest(ctx, p, i+1)
			r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Failed, Err: err})
			return err
		}

		r.emit(ctx, Event{Kind: KindStep, Project: p.Project, Step: s.Name(), Status: Done})
	}

	r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Done})
	return nil
}

// skipRest marks every step from index i onwards as skipped.
func (r *Runner) skipRest(ctx context.Context, p Pipeline, i int) {
	for ; i < len(p.Steps); i++ {
		r.emit(ctx, Event{Kind: KindStep, Project: p.Project, Step: p.Steps[i].Name(), Status: Skipped})
	}
}

func (r *Runner) emit(ctx context.Context, ev Event) {
	select {
	case r.ch <- ev:
	case <-ctx.Done():
	}
}
